thread_local! {
    /// Cached render entities so repeated renders reuse the same GPUI entity.
    // Stored as weak references so GPUI can drop the entity when the view is
    // destroyed; otherwise tests report leaked entity handles.
    static TABS_ENTITIES: RefCell<HashMap<ElementId, WeakEntity<TabsEntity>>> =
        RefCell::new(HashMap::new());
}

/// A tabs component with theming support
pub struct Tabs {
    id: ElementId,
    tabs: Vec<TabItem>,
    selected_index: usize,
    variant: TabVariant,
    theme: Option<TabsTheme>,
    on_change: Option<Rc<dyn Fn(usize, &mut Window, &mut App) + 'static>>,
    on_close: Option<Rc<dyn Fn(&SharedString, &mut Window, &mut App) + 'static>>,
    focus_handle: Option<FocusHandle>,
    aria_label: Option<SharedString>,
    aria_role: Option<AriaRole>,
}

impl Tabs {
    /// Create a new tabs component with an ID
    pub fn new(id: impl Into<ElementId>) -> Self {
        Self {
            id: id.into(),
            tabs: Vec::new(),
            selected_index: 0,
            variant: TabVariant::default(),
            theme: None,
            on_change: None,
            on_close: None,
            focus_handle: None,
            aria_label: None,
            aria_role: None,
        }
    }

    /// Set the focus handle for keyboard navigation
    pub fn focus_handle(mut self, handle: FocusHandle) -> Self {
        self.focus_handle = Some(handle);
        self
    }

    /// Set the tab items
    pub fn tabs(mut self, tabs: Vec<TabItem>) -> Self {
        self.tabs = tabs;
        self
    }

    /// Set the selected tab index
    pub fn selected_index(mut self, index: usize) -> Self {
        self.selected_index = index;
        self
    }

    /// Set the visual variant
    pub fn variant(mut self, variant: TabVariant) -> Self {
        self.variant = variant;
        self
    }

    /// Set the theme
    pub fn theme(mut self, theme: TabsTheme) -> Self {
        self.theme = Some(theme);
        self
    }

    /// Set the tab change handler
    pub fn on_change(mut self, handler: impl Fn(usize, &mut Window, &mut App) + 'static) -> Self {
        self.on_change = Some(Rc::new(handler));
        self
    }

    /// Set an explicit ARIA label
    pub fn aria_label(mut self, label: impl Into<SharedString>) -> Self {
        self.aria_label = Some(label.into());
        self
    }

    /// Override the default ARIA role (Tablist)
    pub fn aria_role(mut self, role: AriaRole) -> Self {
        self.aria_role = Some(role);
        self
    }

    /// Set the tab close handler
    pub fn on_close(
        mut self,
        handler: impl Fn(&SharedString, &mut Window, &mut App) + 'static,
    ) -> Self {
        self.on_close = Some(Rc::new(handler));
        self
    }
}

impl Default for Tabs {
    fn default() -> Self {
        Self::new("tabs")
    }
}

/// Internal entity that renders a [`Tabs`] component. The entity is cached by
/// element id so that stable event handlers and hover state persist across
/// renders.
pub struct TabsEntity {
    props: Tabs,
    focus_handle: FocusHandle,
    tab_count: usize,
    hovered_tab: Option<usize>,
    hovered_close: Option<usize>,
    /// Stable tab IDs copied from the last props update so event handlers can
    /// resolve the close target without cloning IDs on every render.
    tab_ids: Vec<SharedString>,
}

impl TabsEntity {
    fn handle_tab_click(
        &mut self,
        index: usize,
        _event: &MouseDownEvent,
        window: &mut Window,
        _cx: &mut Context<Self>,
    ) {
        if let Some(ref handler) = self.props.on_change {
            handler(index, window, _cx);
        }
    }

    fn handle_close_click(
        &mut self,
        index: usize,
        _event: &MouseDownEvent,
        window: &mut Window,
        _cx: &mut Context<Self>,
    ) {
        if let Some(tab_id) = self.tab_ids.get(index) {
            if let Some(ref handler) = self.props.on_close {
                handler(tab_id, window, _cx);
            }
        }
    }

    fn handle_key_down(
        &mut self,
        event: &KeyDownEvent,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        if !self.focus_handle.is_focused(window) {
            return;
        }

        let key = event.keystroke.key.as_str();
        let selected = self.props.selected_index;
        let tab_count = self.tab_count;

        let new_index = match key {
            "left" => {
                if selected > 0 {
                    Some(selected - 1)
                } else {
                    None
                }
            }
            "right" => {
                if selected + 1 < tab_count {
                    Some(selected + 1)
                } else {
                    None
                }
            }
            "home" => Some(0),
            "end" => {
                if tab_count > 0 {
                    Some(tab_count - 1)
                } else {
                    None
                }
            }
            _ => None,
        };

        if let Some(new_idx) = new_index {
            cx.stop_propagation();
            if let Some(ref handler) = self.props.on_change {
                handler(new_idx, window, cx);
            }
        }
    }

    fn set_hovered(&mut self, index: usize, hovered: bool, cx: &mut Context<Self>) {
        let new = if hovered { Some(index) } else { None };
        if self.hovered_tab != new {
            // Only clear if the currently hovered tab matches this one, to
            // avoid race conditions when moving directly between tabs.
            if !hovered && self.hovered_tab != Some(index) {
                return;
            }
            self.hovered_tab = new;
            cx.notify();
        }
    }

    fn set_close_hovered(&mut self, index: usize, hovered: bool, cx: &mut Context<Self>) {
        let new = if hovered { Some(index) } else { None };
        if self.hovered_close != new {
            if !hovered && self.hovered_close != Some(index) {
                return;
            }
            self.hovered_close = new;
            cx.notify();
        }
    }
}

impl Render for TabsEntity {
    fn render(&mut self, _window: &mut Window, cx: &mut Context<Self>) -> impl IntoElement {
        let id = self.props.id.clone();
        let aria_label = self.props.aria_label.clone();
        let aria_role = self.props.aria_role;
        cx.register_accessible(AccessibilityNode {
            element_id: id.clone(),
            label: aria_label.unwrap_or_default(),
            props: AriaProps::with_role(aria_role.unwrap_or(AriaRole::Tablist)),
        });

        let global_theme = cx.theme();
        let tabs_theme = TabsTheme::from(global_theme.as_ref());
        let theme = self.props.theme.clone().unwrap_or(tabs_theme);

        // Capture theme colors as local Copy values.
        let text_hover = theme.text_hover;
        let hover_bg = theme.hover_bg;
        let selected_bg = theme.selected_bg;
        let close_hover_color = theme.close_hover_color;
        let text_selected = theme.text_selected;
        let text_unselected = theme.text_unselected;
        let accent = theme.accent;
        let container_bg = theme.container_bg;
        let container_border = theme.container_border;
        let badge_bg = theme.badge_bg;
        let close_color = theme.close_color;

        let mut container = div()
            .id(id.clone())
            .font_family(global_theme.font_family.clone())
            .track_focus(&self.focus_handle)
            .flex()
            .items_center()
            .focusable();

        // Apply variant-specific container styling
        match self.props.variant {
            TabVariant::Underline => {
                // No border on container - we'll add underlines per-tab
            }
            TabVariant::Enclosed => {
                container = container.gap_1();
            }
            TabVariant::Pills => {
                container = container.gap_2().p_1().bg(container_bg).rounded_lg();
            }
            TabVariant::VerticalCard => {
                container = container
                    .flex_wrap()
                    .gap_2()
                    .p_1()
                    .bg(container_bg)
                    .rounded_lg();
            }
        }

        // Consume the tab list for this render. The props are refreshed before
        // each render by the RenderOnce impl, so the vector will be repopulated.
        let tabs = std::mem::take(&mut self.props.tabs);
        let variant = self.props.variant;

        for (index, tab) in tabs.into_iter().enumerate() {
            let is_selected = index == self.props.selected_index;
            let tab_element_id = tab.tab_element_id;
            let close_element_id = tab.close_element_id;
            let wrapper_element_id = tab.wrapper_element_id;
            let label = tab.label;
            let icon = tab.icon;
            let custom_icon = tab.custom_icon;
            let icon_factory = tab.icon_factory;
            let badge = tab.badge;
            let disabled = tab.disabled;
            let closeable = tab.closeable;

            let hovered = self.hovered_tab == Some(index);
            let close_hovered = self.hovered_close == Some(index);

            // For Underline variant, we wrap the tab content and underline in a flex column
            let tab_element = if variant == TabVariant::Underline {
                let mut tab_content = div()
                    .id(tab_element_id)
                    .flex()
                    .items_center()
                    .gap_2()
                    .px_4()
                    .py_2();

                if is_selected {
                    tab_content = tab_content
                        .text_color(text_selected)
                        .font_weight(FontWeight::SEMIBOLD);
                } else {
                    tab_content = tab_content
                        .text_color(text_unselected)
                        .when(hovered, |s| s.text_color(text_hover));
                }

                if disabled {
                    tab_content = tab_content.opacity(0.5).cursor_not_allowed();
                } else {
                    tab_content = tab_content.cursor_pointer().on_mouse_down(
                        MouseButton::Left,
                        cx.listener(move |this, event: &MouseDownEvent, window, cx| {
                            this.handle_tab_click(index, event, window, cx);
                        }),
                    );
                }

                // Add icon
                if let Some(custom_icon) = custom_icon {
                    tab_content = tab_content.child(custom_icon);
                } else if let Some(icon) = icon {
                    tab_content = tab_content.child(div().text_sm().child(icon));
                }

                // Add label
                tab_content = tab_content.child(div().text_sm().child(label));

                // Add badge
                if let Some(badge) = badge {
                    tab_content = tab_content.child(
                        div()
                            .text_xs()
                            .px_1()
                            .py(px(1.0))
                            .bg(badge_bg)
                            .rounded(px(3.0))
                            .child(badge),
                    );
                }

                // Add close button
                if closeable {
                    let mut close_btn = div()
                        .id(close_element_id)
                        .text_xs()
                        .text_color(close_color)
                        .when(close_hovered, |s| s.text_color(close_hover_color));

                    close_btn = close_btn
                        .on_mouse_down(
                            MouseButton::Left,
                            cx.listener(move |this, event: &MouseDownEvent, window, cx| {
                                this.handle_close_click(index, event, window, cx);
                            }),
                        )
                        .on_hover(cx.listener(
                            move |this: &mut TabsEntity, hovered: &bool, _window, cx| {
                                this.set_close_hovered(index, *hovered, cx);
                            },
                        ));

                    tab_content = tab_content.child(close_btn.child("×"));
                }

                if !disabled {
                    tab_content = tab_content.on_hover(cx.listener(
                        move |this: &mut TabsEntity, hovered: &bool, _window, cx| {
                            this.set_hovered(index, *hovered, cx);
                        },
                    ));
                }

                // Create the underline - accent color for selected, border color for unselected
                let underline = if is_selected {
                    div().h(px(2.0)).w_full().bg(accent)
                } else {
                    div().h(px(1.0)).w_full().bg(container_border)
                };

                // Wrap in a flex column
                div()
                    .id(wrapper_element_id)
                    .flex()
                    .flex_col()
                    .child(tab_content)
                    .child(underline)
            } else if variant == TabVariant::VerticalCard {
                // VerticalCard variant: icon on left (spanning 2 rows), title + number on right
                let mut tab_el = div()
                    .id(tab_element_id)
                    .flex()
                    .items_center()
                    .gap_2()
                    .px_3()
                    .py_2()
                    .min_w(px(90.0));

                if is_selected {
                    tab_el = tab_el.bg(accent).rounded_lg().text_color(text_selected);
                } else {
                    tab_el = tab_el
                        .bg(selected_bg)
                        .rounded_lg()
                        .text_color(text_unselected)
                        .when(hovered, |s| {
                            s.bg(selected_bg)
                                .text_color(text_hover)
                                .shadow(glow_shadow(selected_bg))
                        });
                }

                if disabled {
                    tab_el = tab_el.opacity(0.5).cursor_not_allowed();
                } else {
                    tab_el = tab_el.cursor_pointer().on_mouse_down(
                        MouseButton::Left,
                        cx.listener(move |this, event: &MouseDownEvent, window, cx| {
                            this.handle_tab_click(index, event, window, cx);
                        }),
                    );
                }

                // Icon on left (large, spans both rows visually)
                let icon_color = if is_selected {
                    theme.icon_selected.unwrap_or(text_selected)
                } else {
                    theme.icon_unselected.unwrap_or(accent)
                };
                if let Some(factory) = icon_factory {
                    let icon_element = factory(icon_color);
                    tab_el = tab_el.child(div().flex().items_center().child(icon_element));
                } else if let Some(custom_icon) = custom_icon {
                    tab_el = tab_el.child(
                        div()
                            .flex()
                            .items_center()
                            .text_color(icon_color)
                            .child(custom_icon),
                    );
                } else if let Some(icon) = icon {
                    tab_el = tab_el.child(
                        div()
                            .flex()
                            .items_center()
                            .text_xl()
                            .text_color(icon_color)
                            .child(icon),
                    );
                }

                // Right side: Title on top, Number below
                let mut right_col = div().flex().flex_col().gap(px(1.0));

                right_col = right_col.child(
                    div()
                        .text_xs()
                        .font_weight(if is_selected {
                            FontWeight::SEMIBOLD
                        } else {
                            FontWeight::NORMAL
                        })
                        .child(label),
                );

                if let Some(badge) = badge {
                    right_col =
                        right_col.child(div().text_sm().font_weight(FontWeight::BOLD).child(badge));
                }

                tab_el = tab_el.child(right_col);

                tab_el.on_hover(cx.listener(
                    move |this: &mut TabsEntity, hovered: &bool, _window, cx| {
                        this.set_hovered(index, *hovered, cx);
                    },
                ))
            } else {
                // Non-underline variants (Enclosed, Pills)
                let mut tab_el = div()
                    .id(tab_element_id)
                    .flex()
                    .items_center()
                    .gap_2()
                    .px_4()
                    .py_2();

                match variant {
                    TabVariant::Enclosed => {
                        if is_selected {
                            tab_el = tab_el
                                .bg(selected_bg)
                                .rounded_t_md()
                                .text_color(text_selected);
                        } else {
                            tab_el = tab_el.text_color(text_unselected).when(hovered, |s| {
                                s.bg(hover_bg)
                                    .text_color(text_hover)
                                    .shadow(glow_shadow(hover_bg))
                            });
                        }
                    }
                    TabVariant::Pills => {
                        if is_selected {
                            tab_el = tab_el.bg(accent).rounded_md().text_color(text_selected);
                        } else {
                            tab_el = tab_el.rounded_md().text_color(text_unselected).when(
                                hovered,
                                |s| {
                                    s.bg(selected_bg)
                                        .text_color(text_hover)
                                        .shadow(glow_shadow(selected_bg))
                                },
                            );
                        }
                    }
                    TabVariant::Underline | TabVariant::VerticalCard => unreachable!(),
                }

                if disabled {
                    tab_el = tab_el.opacity(0.5).cursor_not_allowed();
                } else {
                    tab_el = tab_el.cursor_pointer().on_mouse_down(
                        MouseButton::Left,
                        cx.listener(move |this, event: &MouseDownEvent, window, cx| {
                            this.handle_tab_click(index, event, window, cx);
                        }),
                    );
                }

                // Add icon
                if let Some(custom_icon) = custom_icon {
                    tab_el = tab_el.child(custom_icon);
                } else if let Some(icon) = icon {
                    tab_el = tab_el.child(div().text_sm().child(icon));
                }

                // Add label
                tab_el = tab_el.child(div().text_sm().child(label));

                // Add badge
                if let Some(badge) = badge {
                    tab_el = tab_el.child(
                        div()
                            .text_xs()
                            .px_1()
                            .py(px(1.0))
                            .bg(badge_bg)
                            .rounded(px(3.0))
                            .child(badge),
                    );
                }

                // Add close button
                if closeable {
                    let mut close_btn = div()
                        .id(close_element_id)
                        .text_xs()
                        .text_color(close_color)
                        .when(close_hovered, |s| s.text_color(close_hover_color));

                    close_btn = close_btn
                        .on_mouse_down(
                            MouseButton::Left,
                            cx.listener(move |this, event: &MouseDownEvent, window, cx| {
                                this.handle_close_click(index, event, window, cx);
                            }),
                        )
                        .on_hover(cx.listener(
                            move |this: &mut TabsEntity, hovered: &bool, _window, cx| {
                                this.set_close_hovered(index, *hovered, cx);
                            },
                        ));

                    tab_el = tab_el.child(close_btn.child("×"));
                }

                tab_el.on_hover(cx.listener(
                    move |this: &mut TabsEntity, hovered: &bool, _window, cx| {
                        this.set_hovered(index, *hovered, cx);
                    },
                ))
            };

            container = container.child(tab_element);
        }

        // Add keyboard navigation
        container = container.on_key_down(cx.listener(|this, event: &KeyDownEvent, window, cx| {
            this.handle_key_down(event, window, cx);
        }));

        container
    }
}

impl RenderOnce for Tabs {
    fn render(self, _window: &mut Window, cx: &mut App) -> impl IntoElement {
        let id = self.id.clone();
        let focus_handle = self
            .focus_handle
            .clone()
            .unwrap_or_else(|| cx.focus_handle());
        let tab_count = self.tabs.len();

        let entity: Entity<TabsEntity> = TABS_ENTITIES.with(|map| {
            let mut map = map.borrow_mut();
            if let Some(weak) = map.get(&id) {
                if let Some(entity) = weak.upgrade() {
                    return entity;
                }
            }
            let entity = cx.new(|_cx| TabsEntity {
                props: Tabs::new(id.clone()),
                focus_handle: focus_handle.clone(),
                tab_count,
                hovered_tab: None,
                hovered_close: None,
                tab_ids: Vec::new(),
            });
            map.insert(id.clone(), entity.downgrade());
            entity
        });
        entity.update(cx, |model, _cx| {
            model.tab_count = tab_count;
            model.tab_ids = self.tabs.iter().map(|tab| tab.id.clone()).collect();
            model.props = self;
        });
        entity
    }
}

impl IntoElement for Tabs {
    type Element = gpui::Component<Self>;

    fn into_element(self) -> Self::Element {
        gpui::Component::new(self)
    }
}
